    sid = _bus["seq"]
    _bus["handlers"].setdefault(event, []).append((sid, handler))
    return sid

def emit(event, *args):
    for sid, handler in list(_bus["handlers"].get(event, [])):
        try:
            handler(*args)
        except Exception:
            continue

def map_emit(event, *args):
    return [handler(*args) for sid, handler in list(_bus["handlers"].get(event, []))]

def clear(event):
